def is_woodall(n):
    # Check if the number is greater than 1
    if n <= 1:
        return False

    # Check if the number is Woodall
    # A Woodall number is of the form 2^p - 1, where p is a prime number
    # We can iterate through all prime numbers to check if n is of the form 2^p - 1
    for p in range(2, n):
        if pow(2, p) - 1 == n:
            return True
    return False

